mapper.select:
select `e`.*,d.drug_name, u.real_name from `exchange` e   left join `drug` d on e.drug_id = d.id
   left join `user` u on e.user_id = u.id
   where 1=1
   
       and `e`.id = #{id}
   
    
        and  e.order_number like concat('%',#{orderNumber},'%')
    
    
        and e.drug_id = #{drugId}
    
    
        and e.user_id = #{userId}
    
    
        and e.status = #{status}
    
    
        and d.drug_name like concat('%',#{drugName},'%')
    
        
        and u.real_name like concat('%',#{realName},'%')
    
    order by `e`.create_time desc
